with numbered_assets as (
  select
    a.id,
    a.hub_id,
    th.tenant_id,
    row_number() over (order by a.hub_id, a.reference_tag, a.id) as rn
  from public.assets a
  join public.tenant_hubs th on th.id = a.hub_id
),
selected as (
  select
    na.id,
    na.hub_id,
    na.tenant_id,
    na.rn,
    case
      when (na.rn / 4) % 5 < 3 then 1
      else 2 + ((na.rn / 4) % 3)
    end as record_count
  from numbered_assets na
  where na.rn % 4 = 0
),
expanded as (
  select
    s.id as asset_id,
    s.hub_id,
    s.tenant_id,
    s.rn,
    series.n as record_index
  from selected s
  cross join lateral generate_series(1, s.record_count::integer) as series(n)
),
hub_staff as (
  select *
  from (
    values
      ('55555555-5555-4555-8555-555555555551'::uuid, '33333333-3333-4333-8333-333333333331'::uuid, '33333333-3333-4333-8333-333333333335'::uuid),
