  ) as staff(hub_id, admin_user_id, member_user_id)
),
part_sets as (
  select *
  from (
    values
      (0, array['brake pads', 'brake cable']::text[]),
      (1, array['chain', 'cassette']::text[]),
      (2, array['inner tube', 'tyre']::text[]),
      (3, array['gear cable', 'chain']::text[]),
      (4, array['brake pads']::text[]),
      (5, array['spokes', 'rim tape']::text[])
  ) as parts(idx, parts)
),
descriptions as (
  select *
  from (
    values
      (0, 'Routine safety inspection completed.'),
      (1, 'Replaced worn brake pads and adjusted cable tension.'),
      (2, 'Cleaned and lubricated the drivetrain.'),
      (3, 'Replaced the inner tube after a puncture.'),
      (4, 'Trued the wheel and replaced a broken spoke.'),
      (5, 'Full service: adjusted gears, brakes, and bearings.')
  ) as descriptions(idx, description)
)
insert into public.maintenance_records (
  asset_id,
  parts,
  created_by,
  metadata,
  service_type,
  created_at
)
select
  e.asset_id,
  ps.parts,
  hu.id,
  jsonb_build_object('description', d.description),
  st.id,
  now()
    - (((e.rn % 450) + 1) * interval '1 day')
    - (((e.record_index - 1) * (7 + (e.rn % 21))) * interval '1 day')
from expanded e
join hub_staff hs on hs.hub_id = e.hub_id
join public.hub_users hu
  on hu.hub_id = e.hub_id
 and hu.user_id = case
   when (e.rn / 4) % 2 = 0 then hs.admin_user_id
   else hs.member_user_id
 end
join part_sets ps on ps.idx = ((e.rn + e.record_index) % 6)
join descriptions d on d.idx = ((e.rn + e.record_index) % 6)
join public.service_types st
  on st.tenant_id = e.tenant_id
 and st.type_name = case (e.rn + e.record_index) % 5
        when 0 then 'Safety check'
        when 1 then 'Brake service'
        when 2 then 'Drivetrain service'
        when 3 then 'Wheel service'
        when 4 then 'Full service'
      end;
